"""GENERATED by make_tk_core.py -- do not edit.  Teacher-hooked rollout + teacher-box KL for methods TK1/TK2/TK3."""
import lowres_patch  # noqa: F401  (patched encode_chat must be in place before the v1_core globals are copied)
import torch
import v1_core

globals().update({k: v for k, v in vars(v1_core).items() if not k.startswith("__")})


@torch.no_grad()
def rollout_trajectory_tk(
    vlm,
    head: OrderedBoxHead,
    processor,
    orig_image: Image.Image,
    user_text: str,
    execution_mode: str,
    decode_mode: str,
    device: str,
    orig_max_pixels: int = 1048576,
    crop_max_pixels: int = 1048576,
    max_crops: int = 3,
    max_turns: int = 5,
    max_new_tokens_per_turn: int = 512,
    max_new_tokens_total: int = 2048,
    max_context_tokens: int = 8192,
    max_format_feedback: int = 1,
    override_first_box_1000: Optional[List[int]] = None,
    teacher_hook=None,
) -> Dict[str, Any]:
    """Unified rollout engine for 'text' and 'continuous_head' modes."""
    assert execution_mode in ("text", "continuous_head")
    assert decode_mode in ("train", "eval")
    training = decode_mode == "train"
    vlm.eval()
    head.eval()

    messages = [
        dict(role="system", content=SYSTEM_PROMPT),
        dict(role="user", content=[dict(type="image"), dict(type="text", text=user_text)]),
    ]
    images = [orig_image]
    turns = []
    actions = []
    final_answer = None
    termination_reason = "max_turns_reached"
    format_errors = 0
    total_new_tokens = 0

    for turn_idx in range(max_turns):
        prefix_inputs = encode_chat(processor, messages, images, max_pixels=orig_max_pixels)
        prompt_len = int(prefix_inputs["input_ids"].shape[-1])
        rem_tokens = min(max_new_tokens_per_turn, max_new_tokens_total - total_new_tokens)
        if rem_tokens <= 0 or prompt_len + rem_tokens > max_context_tokens:
            termination_reason = "context_or_token_budget_exceeded"
            break

        # Stage 1: generate free text up to '...\"bbox\":[' or '</final>' or '</tool_call>'
        with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
            gen1 = vlm.generate(
                **to_device(prefix_inputs, device),
                do_sample=training,
                temperature=1.0,
                top_p=1.0 if training else 1.0,
                max_new_tokens=rem_tokens,
                use_cache=True,
                stopping_criteria=StoppingCriteriaList([
                    StopAtBoxPrefixOrTerminal(processor.tokenizer, prompt_len, stop_on_box_prefix=True)
                ]),
                pad_token_id=processor.tokenizer.pad_token_id,
            )[0, prompt_len:].cpu()

        gen1_ids = gen1.tolist()
        text1 = processor.tokenizer.decode(gen1_ids, skip_special_tokens=False)
        text1_clean = text1.replace("<|im_end|>", "").replace("<|endoftext|>", "")

        # Check if we stopped at a valid box prefix '...\"bbox\":['
        m_box = BOX_PREFIX_RE.search(text1_clean)
        if m_box and FINAL_CLOSE not in text1_clean[: m_box.start()]:
            # Truncate cleanly right after '"bbox":['
            pre_box_text = text1_clean[: m_box.end()]
            pre_box_inputs = encode_chat(processor, messages, images, suffix=pre_box_text, max_pixels=orig_max_pixels)
            pre_box_len = int(pre_box_inputs["input_ids"].shape[-1])
            pre_box_resp_ids = pre_box_inputs["input_ids"][0, prompt_len:].tolist()

            if len(actions) >= max_crops:
                # Exceeded crop budget
                turns.append(dict(
                    turn_idx=turn_idx,
                    messages=[dict(m) for m in messages],
                    images=list(images),
                    prefix_len=prompt_len,
                    response_ids=pre_box_resp_ids,
                    non_coord_mask=[1.0] * len(pre_box_resp_ids),
                    all_lm_mask=[1.0] * len(pre_box_resp_ids),
                    coord_weighted_mask=[1.0] * len(pre_box_resp_ids),
                    text=pre_box_text,
                    kind="exceeded_crop_budget",
                ))
                total_new_tokens += len(pre_box_resp_ids)
                termination_reason = "exceeded_crop_budget"
                break

            _tk_rec = None
            if execution_mode == "continuous_head":
                head_out = predict_head_box_at_prefix(vlm, head, pre_box_inputs, orig_image, device)
                q = head_out["quantized_box"]
                b_float = head_out["b_float"]
                if override_first_box_1000 is not None and len(actions) == 0:
                    exec_info = execute_crop_1000(orig_image, override_first_box_1000, raw_box=b_float)
                    q = exec_info["quantized_box"]
                else:
                    exec_info = head_out
                forced_suffix = format_canonical_box_suffix(q)
                forced_ids = processor.tokenizer.encode(forced_suffix, add_special_tokens=False)
                full_resp_ids = pre_box_resp_ids + forced_ids
                # Forced coordinate suffix has weight 0 in ALL text KL masks!
                non_coord_mask = [1.0] * len(pre_box_resp_ids) + [0.0] * len(forced_ids)
                all_lm_mask = list(non_coord_mask)
                coord_weighted_mask = list(non_coord_mask)
                full_turn_text = pre_box_text + forced_suffix
                total_new_tokens += len(pre_box_resp_ids)
            else:
                # Text mode: greedily decode the coordinate payload from pre_box_inputs
                with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
                    gen2 = vlm.generate(
                        **to_device(pre_box_inputs, device),
                        do_sample=False,
                        max_new_tokens=48,
                        use_cache=True,
                        stopping_criteria=StoppingCriteriaList([StopAtToolClose(processor.tokenizer, pre_box_len)]),
                        pad_token_id=processor.tokenizer.pad_token_id,
                    )[0, pre_box_len:].cpu()
                coord_ids = gen2.tolist()
                coord_text = processor.tokenizer.decode(coord_ids, skip_special_tokens=False)
                coord_text_clean = coord_text.replace("<|im_end|>", "").replace("<|endoftext|>", "")
                close_pos = coord_text_clean.find(TOOL_CLOSE)
                if close_pos >= 0:
                    coord_text_clean = coord_text_clean[: close_pos + len(TOOL_CLOSE)]
                    coord_ids = processor.tokenizer.encode(coord_text_clean, add_special_tokens=False)
                full_turn_text = pre_box_text + coord_text_clean
                full_resp_ids = pre_box_resp_ids + coord_ids
                non_coord_mask = [1.0] * len(pre_box_resp_ids) + [0.0] * len(coord_ids)
                all_lm_mask = [1.0] * len(pre_box_resp_ids) + [1.0] * len(coord_ids)
                coord_weighted_mask = [1.0] * len(pre_box_resp_ids) + [4.0] * len(coord_ids)
                total_new_tokens += len(full_resp_ids)

                try:
                    raw_vals = parse_box_from_tool_text(full_turn_text[m_box.start() :])
                    if override_first_box_1000 is not None and len(actions) == 0:
                        exec_info = execute_crop_1000(orig_image, override_first_box_1000)
                    else:
                        exec_info = execute_crop_1000(orig_image, raw_vals)
                    b_float = [v / 1000.0 for v in exec_info["quantized_box"]]
                    if teacher_hook is not None:
                        _tk_rec = teacher_hook(pre_box_inputs, exec_info, messages, images, pre_box_text)
                        if _tk_rec.get("reset"):
                            exec_info = _tk_rec["exec_info"]
                            b_float = [v / 1000.0 for v in exec_info["quantized_box"]]
                            coord_text_clean = _tk_rec["suffix_text"]
                            coord_ids = processor.tokenizer.encode(coord_text_clean, add_special_tokens=False)
                            full_turn_text = pre_box_text + coord_text_clean
                            full_resp_ids = pre_box_resp_ids + coord_ids
                            non_coord_mask = [1.0] * len(pre_box_resp_ids) + [0.0] * len(coord_ids)
                            all_lm_mask = [1.0] * len(full_resp_ids)
                            coord_weighted_mask = [1.0] * len(pre_box_resp_ids) + [4.0] * len(coord_ids)
                except CropProtocolError as exc:
                    turns.append(dict(
                        turn_idx=turn_idx,
                        messages=[dict(m) for m in messages],
                        images=list(images),
                        prefix_len=prompt_len,
                        response_ids=full_resp_ids,
                        non_coord_mask=non_coord_mask,
                        all_lm_mask=all_lm_mask,
                        coord_weighted_mask=coord_weighted_mask,
                        text=full_turn_text,
                        kind="invalid_crop_call",
                        error=str(exc),
                    ))
                    format_errors += 1
                    if format_errors > max_format_feedback:
                        termination_reason = f"protocol_error:{exc}"
                        break
                    messages.extend([
                        dict(role="assistant", content=full_turn_text),
                        dict(role="user", content=[dict(type="text", text=FORMAT_FEEDBACK_PROMPT)]),
                    ])
                    continue

            turns.append(dict(
                turn_idx=turn_idx,
                messages=[dict(m) for m in messages],
                images=list(images),
                prefix_len=prompt_len,
                response_ids=full_resp_ids,
                non_coord_mask=non_coord_mask,
                all_lm_mask=all_lm_mask,
                coord_weighted_mask=coord_weighted_mask,
                text=full_turn_text,
                kind="crop",
            ))
            actions.append(dict(
                turn_idx=turn_idx,
                action_idx=len(actions),
                pre_box_messages=[dict(m) for m in messages],
                pre_box_images=list(images),
                pre_box_suffix=pre_box_text,
                b_float=b_float,
                quantized_box=exec_info["quantized_box"],
                executed_pixel_box=exec_info["executed_pixel_box"],
                executed_norm_box=exec_info["executed_norm_box"],
                crop_sha256=exec_info["crop_sha256"],
                crop_wh=exec_info["crop_wh"],
                crop=exec_info["crop"],
                tk=_tk_rec,
            ))
            images.append(exec_info["crop"])
            next_prompt = FORCE_FINAL_PROMPT if len(actions) >= max_crops else FOLLOWUP_PROMPT
            messages.extend([
                dict(role="assistant", content=full_turn_text),
                dict(role="user", content=[dict(type="image"), dict(type="text", text=next_prompt)]),
            ])
            continue

        # Not a box prefix: check if it contains <final>...</final>
        total_new_tokens += len(gen1_ids)
        m_final = FINAL_RE.search(text1_clean)
        if m_final and m_final.group(1).strip():
            final_answer = m_final.group(1).strip()
            end_pos = m_final.end()
            clean_final_text = text1_clean[:end_pos]
            resp_ids = processor.tokenizer.encode(clean_final_text, add_special_tokens=False)
            turns.append(dict(
                turn_idx=turn_idx,
                messages=[dict(m) for m in messages],
                images=list(images),
                prefix_len=prompt_len,
                response_ids=resp_ids,
                non_coord_mask=[1.0] * len(resp_ids),
                all_lm_mask=[1.0] * len(resp_ids),
                coord_weighted_mask=[1.0] * len(resp_ids),
                text=clean_final_text,
                kind="final",
            ))
            termination_reason = "completed_final"
            break

        # Invalid format turn
        turns.append(dict(
            turn_idx=turn_idx,
            messages=[dict(m) for m in messages],
            images=list(images),
            prefix_len=prompt_len,
            response_ids=gen1_ids,
            non_coord_mask=[1.0] * len(gen1_ids),
            all_lm_mask=[1.0] * len(gen1_ids),
            coord_weighted_mask=[1.0] * len(gen1_ids),
            text=text1_clean,
            kind="format_error",
        ))
        format_errors += 1
        if format_errors > max_format_feedback:
            termination_reason = "protocol_error:missing_tool_or_final"
            break
        messages.extend([
            dict(role="assistant", content=text1_clean),
            dict(role="user", content=[dict(type="text", text=FORMAT_FEEDBACK_PROMPT)]),
        ])

    return dict(
        turns=turns,
        actions=actions,
        final_answer=final_answer,
        termination_reason=termination_reason,
        format_errors=format_errors,
        total_new_tokens=total_new_tokens,
        crop_count=len(actions),
        protocol_success=(final_answer is not None and termination_reason == "completed_final"),
    )




def _expand_box_1000(qbox, scale: float):
    x1, y1, x2, y2 = [float(v) for v in qbox]
    cx, cy = 0.5 * (x1 + x2), 0.5 * (y1 + y2)
    w, h = max(4.0, (x2 - x1) * scale), max(4.0, (y2 - y1) * scale)
    nx1 = max(0, min(998, int(round(cx - 0.5 * w))))
    ny1 = max(0, min(998, int(round(cy - 0.5 * h))))
    nx2 = max(nx1 + 2, min(1000, int(round(cx + 0.5 * w))))
    ny2 = max(ny1 + 2, min(1000, int(round(cy + 0.5 * h))))
    return [nx1, ny1, nx2, ny2]


def _cov_and_ratio(s_norm, t_norm):
    iw = max(0.0, min(s_norm[2], t_norm[2]) - max(s_norm[0], t_norm[0]))
    ih = max(0.0, min(s_norm[3], t_norm[3]) - max(s_norm[1], t_norm[1]))
    inter = iw * ih
    ta = max(1e-9, max(0.0, t_norm[2] - t_norm[0]) * max(0.0, t_norm[3] - t_norm[1]))
    sa = max(0.0, s_norm[2] - s_norm[0]) * max(0.0, s_norm[3] - s_norm[1])
    return inter / ta, sa / ta


def make_tk_hook(method, teacher_vlm, teacher_proc, orig_im, device):
    """Called at every crop action of the student's rollout, after the student's own box has been parsed and executed.
    TK1      : only records the teacher's complete box written from the same pre-box state.
    TK2, TK3 : if the student's box and the teacher's box are disjoint (IoU < 0.2), the teacher's box replaces the student's box in the
               trajectory and is the box that gets executed, so the next turn sees the teacher's crop.
    TK3/TKN/TKV2/AT/EF : the teacher writes its reference box from a 1MP view of the overview (the student keeps its 0.25MP view).
    AT       : Acceptable Box Set A_T (accepts student box if it covers >=85% of teacher box within <=3.5x area, or IoU>=0.5).
    EF       : Crop-Effect Consequence Distillation (compares student crop, teacher tight crop, and 1.5x expanded teacher crop by how well
               the 0.25MP overview + crop lets the teacher read the reference answer)."""
    def hook(pre_box_inputs, exec_info, messages, images, pre_box_text):
        if method in ("TK3", "TKN", "TKV2", "AT", "ATG", "EF", "QK"):
            t_in = lowres_patch._ORIG_ENCODE_CHAT(teacher_proc, messages, list(images), suffix=pre_box_text, max_pixels=1048576)
        else:
            t_in = pre_box_inputs
        t_info = query_teacher_box(teacher_vlm, teacher_proc, t_in, orig_im, device)
        rec = dict(valid=bool(t_info["valid"]), t_info=t_info, s_in=pre_box_inputs,
                   t_in=(t_in if method in ("TK3", "TKN", "TKV2", "AT", "ATG", "EF", "QK") else None),
                   iou=None, cov_t=None, ratio_t=None, in_at=False, ef_accept=False, ef_gain=0.0, ef_w=0.25,
                   reset=False, student_box=list(exec_info["quantized_box"]))
        if t_info["valid"]:
            rec["iou"] = box_iou_float(exec_info["executed_norm_box"], t_info["executed_norm_box"])
            cov_t, ratio_t = _cov_and_ratio(exec_info["executed_norm_box"], t_info["executed_norm_box"])
            rec["cov_t"] = cov_t
            rec["ratio_t"] = ratio_t
            if method in ("TK2", "TK3") and rec["iou"] < 0.2:
                rec["reset"] = True
                rec["exec_info"] = execute_crop_1000(orig_im, t_info["quantized_box"])
                rec["suffix_text"] = t_info["canonical_suffix"]
            elif method in ("AT", "ATG", "QK"):
                rec["in_at"] = bool((cov_t >= 0.85 and ratio_t <= 3.5) or (rec["iou"] >= 0.50))
                if method == "AT" and not rec["in_at"] and cov_t < 0.50:
                    exp_q = _expand_box_1000(t_info["quantized_box"], 1.35)
                    rec["t_info"] = dict(t_info)
                    rec["t_info"]["target_suffix_ids"] = teacher_proc.tokenizer.encode(
                        format_canonical_box_suffix(exp_q), add_special_tokens=False
                    )
            elif method == "EF":
                b_s = list(exec_info["quantized_box"])
                b_t = list(t_info["quantized_box"])
                b_e = _expand_box_1000(b_t, 1.5)
                crop_s = exec_info["crop"]
                crop_t = execute_crop_1000(orig_im, b_t)["crop"]
                crop_e = execute_crop_1000(orig_im, b_e)["crop"]
                # Reference answer y^T generated by 1MP teacher with its own box text and crop
                msgs_t = [dict(m) for m in messages] + [
                    dict(role="assistant", content=pre_box_text + format_canonical_box_suffix(b_t)),
                    dict(role="user", content=[dict(type="image"), dict(type="text", text=FOLLOWUP_PROMPT)]),
                ]
                ref_in = lowres_patch._ORIG_ENCODE_CHAT(teacher_proc, msgs_t, list(images) + [crop_t], suffix="<final>", max_pixels=1048576)
                r_plen = int(ref_in["input_ids"].shape[-1])
                with torch.no_grad(), torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
                    gen_a = teacher_vlm.generate(
                        **to_device(ref_in, device), do_sample=False, max_new_tokens=24, use_cache=True,
                        pad_token_id=teacher_proc.tokenizer.pad_token_id,
                    )[0, r_plen:].cpu().tolist()
                ans_txt = teacher_proc.tokenizer.decode(gen_a, skip_special_tokens=False)
                if "</final>" in ans_txt:
                    ans_txt = ans_txt[: ans_txt.find("</final>") + len("</final>")]
                    ans_ids = teacher_proc.tokenizer.encode(ans_txt, add_special_tokens=False)
                else:
                    ans_ids = gen_a[:24]
                if not ans_ids:
                    ans_ids = gen_a[:1] if gen_a else [teacher_proc.tokenizer.eos_token_id or 1]

                def _score_crop(qbox, c_im):
                    # Action-observation consistent history: tool call text matches qbox AND image matches c_im
                    cand_suf = format_canonical_box_suffix(qbox)
                    msgs_c = [dict(m) for m in messages] + [
                        dict(role="assistant", content=pre_box_text + cand_suf),
                        dict(role="user", content=[dict(type="image"), dict(type="text", text=FOLLOWUP_PROMPT)]),
                    ]
                    c_in = encode_chat(teacher_proc, msgs_c, list(images) + [c_im], suffix="<final>", max_pixels=1048576)
                    d = to_device(c_in, device)
                    plen = int(d["input_ids"].shape[-1])
                    tgt = torch.tensor([ans_ids], dtype=d["input_ids"].dtype, device=device)
                    fd = dict(d)
                    fd["input_ids"] = torch.cat([d["input_ids"], tgt], dim=-1)
                    fd["attention_mask"] = torch.ones_like(fd["input_ids"])
                    with torch.no_grad(), torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
                        h = teacher_vlm.model(**fd, use_cache=False, return_dict=True).last_hidden_state[0, plen - 1 : plen - 1 + len(ans_ids)]
                        lp = F.log_softmax(teacher_vlm.lm_head(h).float(), dim=-1)
                    return float(lp.gather(-1, tgt[0].unsqueeze(-1)).mean().item())

                sc_s = _score_crop(b_s, crop_s)
                sc_t = _score_crop(b_t, crop_t)
                sc_e = _score_crop(b_e, crop_e)
                best_sc = max(sc_t, sc_e)
                gain = best_sc - sc_s
                rec["ef_gain"] = gain
                # Deduplicate candidate boxes while preserving order (student, tight teacher, expanded teacher)
                seen_b = set()
                ef_cands = []
                for qb, sc in ((b_s, sc_s), (b_t, sc_t), (b_e, sc_e)):
                    key_b = tuple(qb)
                    if key_b not in seen_b:
                        seen_b.add(key_b)
                        c_ids = teacher_proc.tokenizer.encode(format_canonical_box_suffix(qb), add_special_tokens=False)
                        ef_cands.append((c_ids, float(sc)))
                rec["ef_cands"] = ef_cands
                if gain <= 0.10 or len(ef_cands) < 2:
                    rec["ef_accept"] = True
                else:
                    rec["ef_accept"] = False
                    rec["ef_w"] = min(0.50, max(0.15, 0.25 * gain))
        return rec
    return hook


def ef_candidate_loss(student_vlm, rec, device, tau: float = 0.25):
    """Candidate-level consequence distillation over C = {b_S, b_T, b_E}:
    Optimizes D_KL(q_effect || p_S^cand) + 0.5 * (-sum_j q_j * ell_S(b_j)) directly on the student's sequence log-probs."""
    cands = rec.get("ef_cands") or []
    if len(cands) < 2:
        return torch.zeros((), dtype=torch.float32, device=device, requires_grad=True), 0.0
    s_in = to_device(rec["s_in"], device)
    s_plen = int(s_in["input_ids"].shape[-1])
    ell_list = []
    mean_len = 0.0
    for c_ids, _sc in cands:
        L = len(c_ids)
        mean_len += L
        tgt = torch.tensor([c_ids], dtype=s_in["input_ids"].dtype, device=device)
        fd = dict(s_in)
        fd["input_ids"] = torch.cat([s_in["input_ids"], tgt], dim=-1)
        fd["attention_mask"] = torch.ones_like(fd["input_ids"])
        with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
            sh = student_vlm.model(**fd, use_cache=False, return_dict=True).last_hidden_state[0, s_plen - 1 : s_plen - 1 + L]
        lp = F.log_softmax(student_vlm.lm_head(sh).float(), dim=-1)
        seq_lp = lp.gather(-1, tgt[0].unsqueeze(-1)).squeeze(-1).mean()
        ell_list.append(seq_lp)
    mean_len /= len(cands)
    ells = torch.stack(ell_list)
    scores = torch.tensor([sc for _, sc in cands], dtype=torch.float32, device=device)
    with torch.no_grad():
        q = F.softmax(scores / tau, dim=-1)
    log_pc = F.log_softmax(ells, dim=-1)
    kl_c = (q * (q.clamp_min(1e-12).log() - log_pc)).sum()
    anchor = -(q * ells).sum()
    loss_per_tok = 0.5 * kl_c + 0.5 * anchor
    return loss_per_tok * mean_len, float(mean_len)


QKL_STATS = dict(n_pos=0, n_empty=0, sum_fsize=0, n_candidates=0, n_turns=0)


def _qkl_accept(qbox, teacher_box):
    s_norm = [float(v) / 1000.0 for v in qbox]
    t_norm = [float(v) / 1000.0 for v in teacher_box]
    cov_t, ratio_t = _cov_and_ratio(s_norm, t_norm)
    iou = box_iou_float(s_norm, t_norm)
    return bool((cov_t >= 0.85 and ratio_t <= 3.5) or iou >= 0.50)


def build_qkl_candidate_boxes(teacher_box, student_box):
    """Finite candidate approximation of A_T: teacher box, context-preserving expansions/shifts,
    and the student's box when it is itself acceptable. No GT boxes or answers are used."""
    tx1, ty1, tx2, ty2 = [int(v) for v in teacher_box]
    tw, th = max(2, tx2 - tx1), max(2, ty2 - ty1)
    raw = [list(teacher_box), list(student_box)]
    raw.extend(_expand_box_1000(teacher_box, sc) for sc in (1.15, 1.35, 1.50))
    for fx, fy in ((-0.05, 0.0), (0.05, 0.0), (0.0, -0.05), (0.0, 0.05),
                   (-0.05, -0.05), (-0.05, 0.05), (0.05, -0.05), (0.05, 0.05)):
        dx, dy = int(round(fx * tw)), int(round(fy * th))
        raw.append([tx1 + dx, ty1 + dy, tx2 + dx, ty2 + dy])
    out, seen = [], set()
    for q in raw:
        q = [max(0, min(1000, int(v))) for v in q]
        if q[2] <= q[0] or q[3] <= q[1] or not _qkl_accept(q, teacher_box):
            continue
        key = tuple(q)
        if key not in seen:
            seen.add(key)
            out.append(q)
    return out[:32]


def build_qkl_feasible_sets(tokenizer, pre_box_text, coord_ids, candidate_boxes):
    """F_j contains next tokens that can still complete one finite candidate acceptable box
    along the student's actual visited prefix. Empty F means that no candidate can repair it."""
    pre_ids = tokenizer.encode(pre_box_text, add_special_tokens=False)
    suffix_ids = []
    for q in candidate_boxes:
        full_ids = tokenizer.encode(pre_box_text + format_canonical_box_suffix(q), add_special_tokens=False)
        if full_ids[:len(pre_ids)] == pre_ids:
            suffix_ids.append(full_ids[len(pre_ids):])
    coord_ids = list(coord_ids)
    feasible = []
    for j in range(len(coord_ids)):
        fj = set()
        for ids in suffix_ids:
            if j < len(ids) and ids[:j] == coord_ids[:j]:
                fj.add(ids[j])
        feasible.append(sorted(fj))
    QKL_STATS['n_pos'] += len(feasible)
    QKL_STATS['n_empty'] += sum(not f for f in feasible)
    QKL_STATS['sum_fsize'] += sum(len(f) for f in feasible)
    QKL_STATS['n_candidates'] += len(suffix_ids)
    QKL_STATS['n_turns'] += 1
    return feasible


def _qkl_chunk_fn(s_h, t_h, w, feasible, s_lm_head, t_lm_head):
    """Reverse KL after merging all feasible next tokens into one category.
    Equals ordinary KL minus the within-feasible-set conditional KL."""
    s_logits = s_lm_head(s_h).float()
    with torch.no_grad():
        t_logits = t_lm_head(t_h).float()
        t_logits = torch.where(torch.isfinite(t_logits), t_logits, torch.zeros_like(t_logits))
        log_pt = F.log_softmax(t_logits, dim=-1)
    log_ps = F.log_softmax(s_logits, dim=-1)
    ps = log_ps.exp()
    token_kl = (ps * (log_ps - log_pt)).sum(dim=-1)
    terms = []
    for i, fset in enumerate(feasible):
        term = token_kl[i]
        if fset:
            idx = torch.tensor(fset, dtype=torch.long, device=log_ps.device)
            lp_s = log_ps[i].index_select(0, idx)
            lp_t = log_pt[i].index_select(0, idx)
            in_kl = (lp_s.exp() * (lp_s - lp_t)).sum()
            log_ms = torch.logsumexp(lp_s, dim=0)
            log_mt = torch.logsumexp(lp_t, dim=0)
            group_kl = log_ms.exp() * (log_ms - log_mt)
            term = term - in_kl + group_kl
        terms.append(term)
    return (torch.stack(terms) * w).sum()


def compute_turn_kl_loss_qkl(
    student_vlm,
    teacher_vlm,
    s_prefix_inputs,
    t_hi_prefix_inputs,
    response_ids,
    non_coord_mask,
    feasible_by_pos,
    coord_weight: float = 0.5,
    device: str = 'cuda:0',
    chunk_size: int = 64,
    use_recompute: bool = True,
):
    """H_S view decoupling with QKL on coordinate positions and ordinary OPD elsewhere."""
    L = len(response_ids)
    assert L == len(non_coord_mask) == len(feasible_by_pos) and L > 0
    if not any(m == 0.0 for m in non_coord_mask):
        return compute_turn_kl_loss(student_vlm, teacher_vlm, s_prefix_inputs, response_ids,
                                    non_coord_mask, device, chunk_size=chunk_size, use_recompute=use_recompute)
    weights = [1.0 if m > 0.0 else float(coord_weight) for m in non_coord_mask]
    w_tensor = torch.tensor(weights, dtype=torch.float32, device=device)
    w_sum = float(w_tensor.sum().item())

    def _full(inp):
        d = to_device(inp, device)
        plen = int(d['input_ids'].shape[-1])
        resp = torch.tensor([response_ids], dtype=d['input_ids'].dtype, device=device)
        fd = dict(d)
        fd['input_ids'] = torch.cat([d['input_ids'], resp], dim=-1)
        fd['attention_mask'] = torch.ones_like(fd['input_ids'])
        return fd, plen

    s_fd, s_plen = _full(s_prefix_inputs)
    t_fd, t_plen = _full(t_hi_prefix_inputs)
    with torch.no_grad(), torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
        t_lo_h = teacher_vlm.model(**s_fd, use_cache=False, return_dict=True).last_hidden_state[0, s_plen - 1:s_plen - 1 + L].detach()
        t_hi_h = teacher_vlm.model(**t_fd, use_cache=False, return_dict=True).last_hidden_state[0, t_plen - 1:t_plen - 1 + L].detach()
        is_coord = torch.tensor([m == 0.0 for m in non_coord_mask], dtype=torch.bool, device=device).unsqueeze(-1)
        t_hidden = torch.where(is_coord, t_hi_h, t_lo_h)
    with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
        s_hidden = student_vlm.model(**s_fd, use_cache=False, return_dict=True).last_hidden_state[0, s_plen - 1:s_plen - 1 + L]

    total = None
    for start in range(0, L, chunk_size):
        end = min(L, start + chunk_size)
        args = (s_hidden[start:end], t_hidden[start:end], w_tensor[start:end], feasible_by_pos[start:end],
                student_vlm.lm_head, teacher_vlm.lm_head)
        if use_recompute and s_hidden.requires_grad:
            term = grad_checkpoint(_qkl_chunk_fn, *args, use_reentrant=False)
        else:
            term = _qkl_chunk_fn(*args)
        total = term if total is None else total + term
    return total, w_sum


def compute_turn_kl_loss_hs(
    student_vlm,
    teacher_vlm,
    s_prefix_inputs,
    t_hi_prefix_inputs,
    response_ids,
    non_coord_mask,
    coord_weight: float,
    device: str,
    chunk_size: int = 64,
    use_recompute: bool = True,
):
    """View-decoupled turn KL (H_S):
    - non-coordinate tokens (non_coord_mask > 0): supervised by 0.25MP teacher (s_prefix_inputs) with weight 1.0
    - coordinate tokens (non_coord_mask == 0): supervised by 1MP teacher (t_hi_prefix_inputs) with weight coord_weight
    Uses a single student forward pass."""
    L = len(response_ids)
    assert L == len(non_coord_mask) and L > 0
    has_coord = coord_weight > 0.0 and any(m == 0.0 for m in non_coord_mask)
    if not has_coord:
        return compute_turn_kl_loss(
            student_vlm, teacher_vlm, s_prefix_inputs, response_ids, non_coord_mask, device, chunk_size=chunk_size, use_recompute=use_recompute
        )

    weights = [1.0 if m > 0.0 else float(coord_weight) for m in non_coord_mask]
    w_tensor = torch.tensor(weights, dtype=torch.float32, device=device)
    w_sum = float(w_tensor.sum().item())
    if w_sum <= 0.0:
        return torch.zeros((), dtype=torch.float32, device=device, requires_grad=True), 0.0

    def _full(inp):
        d = to_device(inp, device)
        plen = int(d["input_ids"].shape[-1])
        resp = torch.tensor([response_ids], dtype=d["input_ids"].dtype, device=device)
        fd = dict(d)
        fd["input_ids"] = torch.cat([d["input_ids"], resp], dim=-1)
        fd["attention_mask"] = torch.ones_like(fd["input_ids"])
        return fd, plen

    s_fd, s_plen = _full(s_prefix_inputs)
    t_hi_fd, t_hi_plen = _full(t_hi_prefix_inputs)
    with torch.no_grad():
        with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
            t_lo_h = teacher_vlm.model(**s_fd, use_cache=False, return_dict=True).last_hidden_state[0, s_plen - 1 : s_plen - 1 + L].detach()
            t_hi_h = teacher_vlm.model(**t_hi_fd, use_cache=False, return_dict=True).last_hidden_state[0, t_hi_plen - 1 : t_hi_plen - 1 + L].detach()
            is_coord = torch.tensor([m == 0.0 for m in non_coord_mask], dtype=torch.bool, device=device).unsqueeze(-1)
            t_hidden = torch.where(is_coord, t_hi_h, t_lo_h)

    with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
        s_out = student_vlm.model(**s_fd, use_cache=False, return_dict=True)
        s_hidden = s_out.last_hidden_state[0, s_plen - 1 : s_plen - 1 + L]

    total_kl = None
    for start in range(0, L, chunk_size):
        end = min(L, start + chunk_size)
        sh_chunk = s_hidden[start:end]
        th_chunk = t_hidden[start:end]
        w_chunk = w_tensor[start:end]
        if float(w_chunk.sum().item()) == 0.0:
            continue
        if use_recompute and sh_chunk.requires_grad:
            term = grad_checkpoint(
                _kl_chunk_fn, sh_chunk, th_chunk, w_chunk, student_vlm.lm_head, teacher_vlm.lm_head, use_reentrant=False
            )
        else:
            term = _kl_chunk_fn(sh_chunk, th_chunk, w_chunk, student_vlm.lm_head, teacher_vlm.lm_head)
        total_kl = term if total_kl is None else total_kl + term
    if total_kl is None:
        return torch.zeros((), dtype=torch.float32, device=device, requires_grad=True), 0.0
    return total_kl, w_sum


def compute_turn_kl_loss_2v(
    student_vlm,
    teacher_vlm,
    s_prefix_inputs,
    t_prefix_inputs,
    response_ids,
    token_weights,
    device: str,
    chunk_size: int = 64,
    use_recompute: bool = True,
):
    """Full-vocab reverse KL over one turn's assistant tokens when student and teacher see different image views (0.25MP vs 1MP)."""
    L = len(response_ids)
    assert L == len(token_weights) and L > 0
    w_tensor = torch.tensor(token_weights, dtype=torch.float32, device=device)
    w_sum = float(w_tensor.sum().item())
    if w_sum <= 0.0:
        return torch.zeros((), dtype=torch.float32, device=device, requires_grad=True), 0.0

    def _full(inp):
        d = to_device(inp, device)
        plen = int(d["input_ids"].shape[-1])
        resp = torch.tensor([response_ids], dtype=d["input_ids"].dtype, device=device)
        fd = dict(d)
        fd["input_ids"] = torch.cat([d["input_ids"], resp], dim=-1)
        fd["attention_mask"] = torch.ones_like(fd["input_ids"])
        return fd, plen

    t_fd, t_plen = _full(t_prefix_inputs)
    with torch.no_grad():
        with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
            t_out = teacher_vlm.model(**t_fd, use_cache=False, return_dict=True)
            t_hidden = t_out.last_hidden_state[0, t_plen - 1 : t_plen - 1 + L].detach()

    s_fd, s_plen = _full(s_prefix_inputs)
    with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
        s_out = student_vlm.model(**s_fd, use_cache=False, return_dict=True)
        s_hidden = s_out.last_hidden_state[0, s_plen - 1 : s_plen - 1 + L]

    total_kl = None
    for start in range(0, L, chunk_size):
        end = min(L, start + chunk_size)
        sh_chunk = s_hidden[start:end]
        th_chunk = t_hidden[start:end]
        w_chunk = w_tensor[start:end]
        if float(w_chunk.sum().item()) == 0.0:
            continue
        if use_recompute and sh_chunk.requires_grad:
            term = grad_checkpoint(
                _kl_chunk_fn, sh_chunk, th_chunk, w_chunk, student_vlm.lm_head, teacher_vlm.lm_head, use_reentrant=False
            )
        else:
            term = _kl_chunk_fn(sh_chunk, th_chunk, w_chunk, student_vlm.lm_head, teacher_vlm.lm_head)
        total_kl = term if total_kl is None else total_kl + term
    if total_kl is None:
        return torch.zeros((), dtype=torch.float32, device=device, requires_grad=True), 0.0
    return total_kl, w_sum


def kl_two_views(student_vlm, teacher_vlm, s_in, t_in, ids, device):
    """Reverse KL D(p_S || p_T) on the tokens `ids` appended to two different prefixes (student view / teacher view)."""
    L = len(ids)

    def full(inp):
        d = to_device(inp, device)
        n = int(d["input_ids"].shape[-1])
        r = torch.tensor([ids], dtype=d["input_ids"].dtype, device=device)
        fd = dict(d)
        fd["input_ids"] = torch.cat([d["input_ids"], r], dim=-1)
        fd["attention_mask"] = torch.ones_like(fd["input_ids"])
        return fd, n

    tf, tn = full(t_in)
    with torch.no_grad():
        with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
            th = teacher_vlm.model(**tf, use_cache=False, return_dict=True).last_hidden_state[0, tn - 1: tn - 1 + L].detach()
    sf, sn = full(s_in)
    with torch.autocast(torch.device(device).type, dtype=torch.bfloat16):
        sh = student_vlm.model(**sf, use_cache=False, return_dict=True).last_hidden_state[0, sn - 1: sn - 1 + L]
    w = torch.ones(L, dtype=torch.float32, device=device)
    return _kl_chunk_fn(sh, th, w, student_vlm.lm_head, teacher_vlm.lm_head), float(L)


def tk_branch_kl(student_vlm, teacher_vlm, rec, device):
    """Token-level reverse KL along the teacher's complete box: inside the box the conditioning prefix is the teacher's box."""
    ids = rec["t_info"]["target_suffix_ids"]
    if rec["t_in"] is None:
        return compute_turn_kl_loss(student_vlm, teacher_vlm, rec["s_in"], ids, [1.0] * len(ids), device, chunk_size=64, use_recompute=True)
    return kl_two_views(student_vlm, teacher_vlm, rec["s_in"], rec["t_in"], ids, device)
